def _normalize_verified_bundle_evolution_checkpoint(
    proof: Any, field: str = "proof"
) -> dict[str, Any]:
    """Run every structural and semantic check on a bundle window proof.

    Enforces the :func:`bundle_evolution_checkpoint` proof contract: exact
    key sets, valid ``start``/``end`` timestamps with ``start <= end``,
    hex64 ``anchor``/``commitment``, a non-empty strictly increasing stage
    chain, fully valid per-stage chain window proof bundles, and adjacent
    diff credentials that reproduce their neighboring bundles. The first
    stage follows the genesis rule (``previous`` of 64 zeroes and ``null``
    diff) or carries the full front-side chain window proof bundle diff
    whose ``after`` bundle reproduces the first stage. Window disorder, an
    illegal change item, or an adjacent diff that does not correspond raises
    ``ValueError``. False declared summaries are carried back as data
    (``bundle_truthful``, ``diff_complete``, and the validated carried-diff
    members) so they yield ``False`` only after every input validates.
    Boundary agreement of ``start``/``end`` with the first/last stage ``at``
    is reported via ``boundaries_ok`` rather than raised. The input is never
    mutated.
    """
    if not isinstance(proof, dict) or set(proof) != set(
        _BUNDLE_EVOLUTION_CHECKPOINT_REPORT_KEYS
    ):
        raise ValueError(
            f"{field} must be a dict with exactly the keys "
            "start, end, anchor, stages, commitment"
        )
    start = _check_time(proof["start"], f"{field}.start")
    end = _check_time(proof["end"], f"{field}.end")
    if start > end:
        raise ValueError(f"{field}.start must not be after {field}.end")
    anchor = _check_hex64(proof["anchor"], f"{field}.anchor")
    commitment = _check_hex64(proof["commitment"], f"{field}.commitment")
    raw_stages = proof["stages"]
    if not isinstance(raw_stages, list) or not raw_stages:
        raise ValueError(f"{field}.stages must be a non-empty list")

    normalized_stages: list[dict[str, Any]] = []
    previous_at: str | None = None
    for index, stage in enumerate(raw_stages):
        stage_field = f"{field}.stages[{index}]"
        if not isinstance(stage, dict) or set(stage) != set(
            _CHECKPOINT_CHAIN_BUNDLE_EVOLUTION_STAGE_KEYS
        ):
            raise ValueError(
                f"{stage_field} must be a dict with exactly the keys "
                "at, bundle, diff, previous, digest"
            )
        at = _check_time(stage["at"], f"{stage_field}.at")
        if previous_at is not None and at <= previous_at:
            raise ValueError(
                f"{stage_field}.at must be strictly greater than the "
                "preceding stage at"
            )
        previous_digest = _check_hex64(
            stage["previous"], f"{stage_field}.previous"
        )
        digest = _check_hex64(stage["digest"], f"{stage_field}.digest")
        bundle_root, bundle_members = (
            _normalize_verified_checkpoint_chain_checkpoint_bundle(
                stage["bundle"], f"{stage_field}.bundle"
            )
        )
        bundle = _canonical_checkpoint_bundle_from_members(
            bundle_root, bundle_members
        )
        bundle_truthful = _chain_checkpoint_bundle_is_truthful(
            bundle_root, bundle_members
        )

        carried_diff: tuple[
            dict[str, Any],
            list[dict[str, Any]],
            list[dict[str, Any]],
            list[dict[str, Any]],
            bool,
        ] | None = None
        if index == 0 and previous_digest == (
            _CHECKPOINT_CHAIN_BUNDLE_EVOLUTION_GENESIS
        ):
            if stage["diff"] is not None:
                raise ValueError(
                    f"{stage_field}.diff must be null at the genesis stage"
                )
            diff: dict[str, Any] | None = None
            diff_complete = True
        elif index == 0:
            diff_content, before_members, after_members, change_entries, complete = (
                _normalize_verified_chain_checkpoint_diff_report(
                    stage["diff"], f"{stage_field}.diff"
                )
            )
            if diff_content["after_root"] != bundle_root:
                raise ValueError(
                    f"{stage_field}.diff.after_root must equal this stage "
                    "bundle root"
                )
            if _chain_checkpoint_bundle_semantics(
                diff_content["after"]
            ) != _chain_checkpoint_bundle_semantics(bundle):
                raise ValueError(
                    f"{stage_field}.diff.after must reproduce this stage bundle"
                )
            diff = diff_content
            diff_complete = complete
            carried_diff = (
                diff_content,
                before_members,
                after_members,
                change_entries,
                complete,
            )
        else:
            preceding = normalized_stages[-1]
            diff_content, _before_members, _after_members, _changes, complete = (
                _normalize_verified_chain_checkpoint_diff_report(
                    stage["diff"], f"{stage_field}.diff"
                )
            )
            if diff_content["before_root"] != preceding["bundle_root"]:
                raise ValueError(
                    f"{stage_field}.diff.before_root must equal the preceding "
                    "stage bundle root"
                )
            if diff_content["after_root"] != bundle_root:
                raise ValueError(
                    f"{stage_field}.diff.after_root must equal this stage "
                    "bundle root"
                )
            if _chain_checkpoint_bundle_semantics(
                diff_content["before"]
            ) != _chain_checkpoint_bundle_semantics(preceding["bundle"]):
                raise ValueError(
                    f"{stage_field}.diff.before must reproduce the preceding "
                    "stage bundle"
                )
            if _chain_checkpoint_bundle_semantics(
                diff_content["after"]
            ) != _chain_checkpoint_bundle_semantics(bundle):
                raise ValueError(
                    f"{stage_field}.diff.after must reproduce this stage bundle"
                )
            diff = diff_content
            diff_complete = complete

        normalized_stages.append(
            {
                "at": at,
                "bundle": bundle,
                "bundle_root": bundle_root,
                "bundle_truthful": bundle_truthful,
                "diff": diff,
                "diff_complete": diff_complete,
                "carried_diff": carried_diff,
                "previous": previous_digest,
                "digest": digest,
            }
        )
        previous_at = at

    boundaries_ok = (
        start == normalized_stages[0]["at"]
        and end == normalized_stages[-1]["at"]
    )
    return {
        "start": start,
        "end": end,
        "anchor": anchor,
        "commitment": commitment,
        "stages": normalized_stages,
        "boundaries_ok": boundaries_ok,
    }


def verify_bundle_evolution_checkpoint(proof: Any, expected: Any) -> bool:
    """Verify a :func:`bundle_evolution_checkpoint` proof without the report.

    Pure function: it only inspects its arguments, touches neither history
    nor files, and never mutates an input object at any level.

    ``proof`` must be a dict with exactly the keys ``start``, ``end``,
    ``anchor``, ``stages``, ``commitment``; ``start``/``end`` must be valid
    UTC seconds with ``start <= end`` and ``anchor``/``commitment`` 64
    lowercase hexadecimal characters. ``stages`` must be a non-empty list of
    full bundle evolution stages whose ``at`` values are strictly
    increasing, whose chain window proof bundles pass every bundle
    structural and embedded-proof semantic check, and whose diffs correspond
    to their neighbors: the genesis stage carries 64 zeroes as ``previous``
    and a ``null`` diff; any other first stage keeps its front-side chain
    window proof bundle diff whose ``after`` bundle reproduces that stage,
    and every later diff must reproduce the preceding and current bundles.
    ``expected`` must have exactly the keys ``start``, ``end``, ``anchor``,
    ``commitment`` and is validated the same way. Exact key sets, times,
    digest formats, stage order, and every embedded credential semantic are
    checked on both inputs first; an illegal structure, disorder, an invalid
    change item, or an adjacent diff that does not correspond raises
    ``ValueError``.

    Only afterwards are values recomputed rather than trusted: every bundle
    chain (including the front-side bundle carried by a non-head first-stage
    diff), the first stage digest seeded from ``anchor`` (the carried diff
    recomputed from its before/after bundles and change proofs), each later
    adjacent :func:`checkpoint_chain_checkpoint_bundle_diff` credential,
    every ``previous``/``digest`` stage link, and the terminal
    ``commitment``. Returns ``False`` for a broken link, a wrong anchor, a
    skipped stage, a tampered diff (including a structurally legal change
    list that omits or invents a change), a boundary mismatch, or any
    ``expected`` disagreement after the structures are legal; otherwise
    ``True``.
    """
    normalized = _normalize_verified_bundle_evolution_checkpoint(proof, "proof")
    if not isinstance(expected, dict) or set(expected) != (
        _BUNDLE_EVOLUTION_CHECKPOINT_EXPECTED_KEYS
    ):
        raise ValueError(
            "expected must be a dict with exactly the keys "
            "start, end, anchor, commitment"
        )
    expected_start = _check_time(expected["start"], "expected.start")
    expected_end = _check_time(expected["end"], "expected.end")
    if expected_start > expected_end:
        raise ValueError("expected.start must not be after expected.end")
    expected_anchor = _check_hex64(expected["anchor"], "expected.anchor")
    expected_commitment = _check_hex64(
        expected["commitment"], "expected.commitment"
    )

    stages = normalized["stages"]
    # Both inputs have now passed every structural and embedded-credential
    # semantic check. Only now recompute and compare; any mismatch yields
    # False rather than raising.
    for stage in stages:
        if not stage["bundle_truthful"]:
            return False
        if stage["carried_diff"] is not None:
            (
                diff_content,
                before_members,
                after_members,
                change_entries,
                complete,
            ) = stage["carried_diff"]
            if not complete:
                return False
            if not _chain_checkpoint_bundle_is_truthful(
                diff_content["before_root"], before_members
            ):
                return False
            if not _chain_checkpoint_bundle_is_truthful(
                diff_content["after_root"], after_members
            ):
                return False
            for change in change_entries:
                for change_proof in (change["before"], change["after"]):
                    if change_proof is not None and not (
                        _checkpoint_chain_checkpoint_is_truthful(change_proof)
                    ):
                        return False
            payload = {
                key: diff_content[key]
                for key in _CHECKPOINT_CHAIN_BUNDLE_DIFF_REPORT_KEYS[:5]
            }
            canonical = json.dumps(
                payload, ensure_ascii=False, separators=(",", ":")
            )
            recomputed_diff_digest = hashlib.sha256(
                canonical.encode("utf-8")
            ).hexdigest()
            if diff_content["digest"] != recomputed_diff_digest:
                return False

    running = normalized["anchor"]
    for index, stage in enumerate(stages):
        if stage["previous"] != running:
            return False
        if index == 0:
            if stage["diff"] is not None:
                recomputed_diff = checkpoint_chain_checkpoint_bundle_diff(
                    stage["diff"]["before"], stage["diff"]["after"]
                )
                if stage["diff"] != recomputed_diff:
                    return False
        else:
            if not stage["diff_complete"]:
                return False
            recomputed_diff = checkpoint_chain_checkpoint_bundle_diff(
                stages[index - 1]["bundle"], stage["bundle"]
            )
            if stage["diff"] != recomputed_diff:
                return False
        recomputed_digest = _chain_checkpoint_bundle_evolution_stage_digest(
            running, stage["at"], stage["bundle"], stage["diff"]
        )
        if stage["digest"] != recomputed_digest:
            return False
        running = recomputed_digest

    if normalized["commitment"] != running:
        return False
    if not normalized["boundaries_ok"]:
        return False
    if (
        normalized["start"] != expected_start
        or normalized["end"] != expected_end
        or normalized["anchor"] != expected_anchor
        or normalized["commitment"] != expected_commitment
    ):
        return False
    return True


def _canonical_bundle_evolution_checkpoint_from_normalized(
    normalized: dict[str, Any],
) -> dict[str, Any]:
    """Rebuild a fresh ``start, end, anchor, stages, commitment`` proof.

    Every level is an independent deep copy of the normalized data produced
    by :func:`_normalize_verified_bundle_evolution_checkpoint`, so the result
    follows the published bundle evolution window proof key order and shares
    no container with the caller's input.
    """
    return {
        "start": normalized["start"],
        "end": normalized["end"],
        "anchor": normalized["anchor"],
        "stages": [
            {
                "at": stage["at"],
                "bundle": copy.deepcopy(stage["bundle"]),
                "diff": copy.deepcopy(stage["diff"]),
                "previous": stage["previous"],
                "digest": stage["digest"],
            }
            for stage in normalized["stages"]
        ],
        "commitment": normalized["commitment"],
    }

def _emit(canonical_json: str) -> dict[str, Any]:
    """Materialize a canonical JSON document as an independent result tree."""
    return _CanonicalDict(json.loads(canonical_json))


class _VKey:
    """A hash-consed composite value key.

    Composite nodes (bundles, diffs, proofs) key their registries by tuples
    of scalar fields plus their children's keys.  Plain tuples re-hash the
    whole nested structure on every lookup; wrapping the tuple caches the
    hash once, so a repeat occurrence resolves in O(1).  Equality still
    compares the full underlying tuple, so distinct values can never merge.
    """

    __slots__ = ("parts", "_hash")

    def __init__(self, parts: Any) -> None:
        self.parts = parts
        self._hash = hash(parts)

    def __hash__(self) -> int:
        return self._hash

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, _VKey):
            return NotImplemented
        return self.parts == other.parts


class _VNode:
    __slots__ = (
        "key", "canonical", "json", "sem", "semkey", "dsem", "dsemkey",
        "truth", "complete",
        "root", "root_after", "members", "before_node", "after_node",
        "digest", "stage_parts",
    )

    def __init__(self) -> None:
        self.key: Any = None
        self.canonical: Any = None
        self.json: str = ""
        self.sem: Any = None
        self.semkey: Any = None
        self.dsem: Any = None
        self.dsemkey: Any = None
        self.truth: bool = False
        self.complete: bool = True
        self.root: str = ""
        self.root_after: str = ""
        self.members: list[Any] = []
        self.before_node: Any = None
        self.after_node: Any = None
        self.digest: str = ""
        self.stage_parts: list[str] = []


class _VEngine:
    def __init__(self) -> None:
        self.cred: dict[str, _VNode] = {}
        self.mbundle: dict[Any, _VNode] = {}
        self.mdiff: dict[Any, _VNode] = {}
        self.p0: dict[Any, _VNode] = {}
        self.b0: dict[Any, _VNode] = {}
        self.d0: dict[Any, _VNode] = {}
        self.p1: dict[Any, _VNode] = {}
        self.b1: dict[Any, _VNode] = {}
        self.d1: dict[Any, _VNode] = {}
        self.p2: dict[Any, _VNode] = {}
        self.b2: dict[Any, _VNode] = {}
        self.d2: dict[Any, _VNode] = {}
        self.p3: dict[Any, _VNode] = {}
        # Generated diffs are fully determined by the two side nodes and the
        # derived change entries; memoizing on those avoids rebuilding the
        # whole five-item payload (and its SHA-256) for a repeated pair.
        self.gen: dict[Any, _VNode] = {}
        # Format checks are pure in the input string, so a validated
        # timestamp or hex64 summary is remembered for the life of the
        # engine (one top-level call) instead of being re-checked at every
        # occurrence.
        self.times: dict[str, str] = {}
        self.hexes: dict[str, str] = {}

    def _time(self, value: Any, field: str) -> str:
        if isinstance(value, str):
            cached = self.times.get(value)
            if cached is not None:
                return cached
        checked = _check_time(value, field)
        self.times[checked] = checked
        return checked

    def _hex64(self, value: Any, field: str) -> str:
        if isinstance(value, str):
            cached = self.hexes.get(value)
            if cached is not None:
                return cached
        checked = _check_hex64(value, field)
        self.hexes[checked] = checked
        return checked

    # ------------------------------------------------------------ leaf cred
    def credential(self, value: Any, field: str) -> _VNode:
        if not isinstance(value, dict):
            raise ValueError(f"{field} must be a credential dict")
        # The reuse identity is a type-faithful structural key, not JSON
        # text: it records the real type of every container and key, so a
        # value that merely serializes like an already-seen credential (an
        # integer fact or condition key where the same digits were verified
        # as a string, a tuple where a list is required) never reuses that
        # credential's verified node.  Such a value falls through to full
        # validation, which reports the structural/type violation as
        # ValueError (never a TypeError), so it is never cached; only a
        # genuine type-and-value match resolves to the cached node.
        key = _VKey(("cred", _vvalue_key(value)))
        node = self.cred.get(key)
        if node is not None:
            return node
        content, declared, recomputed, chain_ok, chain_root = (
            _check_verified_matrix_attestation(value, field)
        )
        # The normalized content is a fresh canonical-order dict owned by
        # this call; appending the declared digest yields the canonical
        # report directly, so no defensive copy is needed before encoding.
        sem = _matrix_credential_semantics(content)
        content["digest"] = declared
        cjson = json.dumps(content, ensure_ascii=False, separators=(",", ":"))
        node = _VNode()
        node.key = key
        node.json = cjson

def matrix_diff(self, value: Any, field: str) -> _VNode:
    return self._parse_diff(
        "mdiff", self.mdiff, value, field,
        lambda v, f: self.matrix_bundle(v, f),
        lambda v, f: self.credential(v, f),
        strict=True,
    )

def proof_diff(self, level: int, value: Any, field: str) -> _VNode:
    tag = {0: "d0", 1: "d1", 2: "d2"}[level]
    registry = (self.d0, self.d1, self.d2)[level]
    bundle_parse = (
        (lambda v, f: self.proof_bundle(0, v, f)),
        (lambda v, f: self.proof_bundle(1, v, f)),
        (lambda v, f: self.proof_bundle(2, v, f)),
    )[level]
    side_parse = (
        self.evolution_proof, self.chain_proof, self.bundle_evolution_proof
    )[level]
    return self._parse_diff(
        tag, registry, value, field, bundle_parse, side_parse, strict=False
    )

def generate_diff(self, level, before: _VNode, after: _VNode) -> _VNode:
    """Canonical diff a generator produces from two canonical bundles."""
    if level == -1:
        tag, registry = "mdiff", self.mdiff
    else:
        tag = {0: "d0", 1: "d1", 2: "d2"}[level]
        registry = (self.d0, self.d1, self.d2)[level]
    before_by_id = {m[0]: m for m in before.members}
    after_by_id = {m[0]: m for m in after.members}
    entries: list[tuple[str, str, _VNode | None, _VNode | None]] = []
    for member_id in sorted(set(before_by_id) | set(after_by_id)):
        bm = before_by_id.get(member_id)
        am = after_by_id.get(member_id)
        if bm is not None and am is not None and bm[1].json == am[1].json:
            continue
        kind = "added" if bm is None else "removed" if am is None else "changed"
        entries.append(
            (member_id, kind, None if bm is None else bm[1],
             None if am is None else am[1])
        )
    change_keys = tuple(
        (i, k, None if bn is None else bn.key, None if an is None else an.key)
        for i, k, bn, an in entries
    )
    memo_key = _VKey((tag, before.key, after.key, change_keys))
    memoized = self.gen.get(memo_key)
    if memoized is not None:
        return memoized
    segments = self._diff_five_segments(
        before.root, after.root, before, after, entries
    )
    digest = self._segments_digest(segments)
    full_key = _VKey(
        (tag, before.root, after.root, digest, before.key, after.key,
         change_keys)
    )
    existing = registry.get(full_key)
    if existing is not None:
        self.gen[memo_key] = existing
        return existing
    node, _digest = self._assemble_diff(
        tag, registry, full_key, before.root, after.root, digest,
        before, after, entries, segments=segments,
    )
    node.truth = True
    node.complete = True
    self.gen[memo_key] = node
    return node

# -------------------------------------------------------------- proofs
def _proof(self, tag, registry, value, field, genesis, bundle_parse,
           diff_level, diff_parse):
    if not isinstance(value, dict) or set(value) != {
        "start", "end", "anchor", "stages", "commitment"
    }:
        raise ValueError(
            f"{field} must be a dict with exactly the keys "
            "start, end, anchor, stages, commitment"
        )
    start = self._time(value["start"], f"{field}.start")
    end = self._time(value["end"], f"{field}.end")
    if start > end:
        raise ValueError(f"{field}.start must not be after {field}.end")
    anchor = self._hex64(value["anchor"], f"{field}.anchor")
    commitment = self._hex64(value["commitment"], f"{field}.commitment")
    raw_stages = value["stages"]
    if not isinstance(raw_stages, list) or not raw_stages:
        raise ValueError(f"{field}.stages must be a non-empty list")

    rows: list[tuple[str, _VNode, _VNode | None, str, str]] = []
    previous_at: str | None = None
    for index, stage in enumerate(raw_stages):
        sf = f"{field}.stages[{index}]"
        if not isinstance(stage, dict) or set(stage) != {
            "at", "bundle", "diff", "previous", "digest"
        }:
            raise ValueError(
                f"{sf} must be a dict with exactly the keys "
                "at, bundle, diff, previous, digest"
            )
        at = self._time(stage["at"], f"{sf}.at")
        if previous_at is not None and at <= previous_at:
            raise ValueError(
                f"{sf}.at must be strictly greater than the preceding stage at"
            )
        prev = self._hex64(stage["previous"], f"{sf}.previous")
        dig = self._hex64(stage["digest"], f"{sf}.digest")
        bundle = bundle_parse(stage["bundle"], f"{sf}.bundle")
        diff: _VNode | None
        if index == 0 and prev == genesis:
            if stage["diff"] is not None:
                raise ValueError(f"{sf}.diff must be null at the genesis stage")
            diff = None
        else:
            diff = diff_parse(stage["diff"], f"{sf}.diff")
            if diff.root_after != bundle.root:
                raise ValueError(
                    f"{sf}.diff.after_root must equal this stage bundle root"
                )
            if diff.after_node.semkey != bundle.semkey:
                raise ValueError(
                    f"{sf}.diff.after must reproduce this stage bundle"
                )
            if index > 0:
                preceding_bundle = rows[-1][1]
                if diff.root != preceding_bundle.root:
                    raise ValueError(
                        f"{sf}.diff.before_root must equal the preceding "
                        "stage bundle root"
                    )
                if diff.before_node.semkey != preceding_bundle.semkey:
                    raise ValueError(
                        f"{sf}.diff.before must reproduce the preceding "
                        "stage bundle"
                    )
        rows.append((at, bundle, diff, prev, dig))
        previous_at = at

    key = _VKey(
        (
            tag, start, end, anchor, commitment,
            tuple(
                (at, b.key, None if d is None else d.key, p, h)
                for at, b, d, p, h in rows
            ),
        )
    )
    node = registry.get(key)
    if node is not None:
        return node

    truth = True
    running = anchor
    stage_parts: list[str] = []
    sem_stages: list[dict[str, Any]] = []
    semkey_stages: list[tuple[str, Any, Any]] = []
    for index, (at, bundle, diff, prev, dig) in enumerate(rows):
        if not bundle.truth:
            truth = False
        if diff is not None:
            if not diff.truth:
                truth = False
            if index == 0:
                generated = self.generate_diff(
                    diff_level, diff.before_node, diff.after_node
                )
            else:
                generated = self.generate_diff(
                    diff_level, rows[index - 1][1], bundle
                )
            # Equal values resolve to the same registry node, so an
            # identity check stands in for comparing the full canonical
            # JSON text of the declared and regenerated diffs.
            if diff is not generated:
                truth = False
        # Hash the stage payload incrementally from the cached child
        # bytes instead of concatenating a throwaway payload string.
        hasher = hashlib.sha256(running.encode("ascii"))
        hasher.update(b'{"at":')
        hasher.update(_vjs(at).encode("utf-8"))
        hasher.update(b',"bundle":')
        hasher.update(bundle.json.encode("utf-8"))
        hasher.update(b',"diff":')
        hasher.update(
            b"null" if diff is None else diff.json.encode("utf-8")
        )
        hasher.update(b"}")
        recomputed = hasher.hexdigest()
        if prev != running or dig != recomputed:
            truth = False
        running = recomputed
        stage_parts.append(
            '{"at":' + _vjs(at)
            + ',"bundle":' + bundle.json
            + ',"diff":' + ("null" if diff is None else diff.json)
            + ',"previous":' + _vjs(prev)
            + ',"digest":' + _vjs(dig) + "}"
        )
        sem_stages.append(
            {
                "at": at,
